const GOLD = "#C9A84C";
const GOLD_BRIGHT = "#E8C040";

function SectionLabel({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    <p
      className="text-[#C9A84C] text-xs tracking-[0.3em] uppercase mb-3"
      style={{
        fontFamily: "'JetBrains Mono', monospace",
        fontWeight: 500,
      }}
    >
      — {children}
    </p>
  );
}

function GoldDivider() {
  return (
    <div className="h-px bg-gradient-to-r from-[#C9A84C] via-[#C9A84C]/60 to-transparent w-20 mt-4" />
  );
}

function PrimaryBtn({
  children,
  onClick,
  className = "",
  disabled = false,
}: {
  children: React.ReactNode;
  onClick?: () => void;
  className?: string;
  disabled?: boolean;
}) {
  return (
    <button
      onClick={onClick}
      disabled={disabled}
      className={`bg-[#C9A84C] text-black font-bold px-8 py-3.5 text-xs tracking-[0.2em] uppercase transition-all duration-300 hover:bg-[#E8C040] disabled:opacity-40 disabled:cursor-not-allowed ${className}`}
      style={{ fontFamily: "'Rajdhani', sans-serif" }}
    >
      {children}
    </button>
  );
}

function OutlineBtn({
  children,
  onClick,
  className = "",
}: {
  children: React.ReactNode;
  onClick?: () => void;
  className?: string;
}) {
  return (
    <button
      onClick={onClick}
      className={`border border-[#C9A84C]/50 text-[#C9A84C] font-bold px-8 py-3.5 text-xs tracking-[0.2em] uppercase transition-all duration-300 hover:border-[#C9A84C] hover:bg-[#C9A84C]/8 ${className}`}
      style={{ fontFamily: "'Rajdhani', sans-serif" }}
    >
      {children}
    </button>
  );
}

