// ─── Navigation ───────────────────────────────────────────────────────────────

const NAV_LINKS: { label: string; page: Page }[] = [
  { label: "Főoldal", page: "home" },
  { label: "Szolgáltatások", page: "services" },
  { label: "Árlista", page: "pricing" },
  { label: "Projektek", page: "projects" },
  { label: "Rólunk", page: "about" },
  { label: "Blog", page: "blog" },
  { label: "Kapcsolat", page: "contact" },
];

function Navigation({
  page,
  setPage,
  dark,
  setDark,
}: {
  page: Page;
  setPage: (p: Page) => void;
  dark: boolean;
  setDark: (d: boolean) => void;
}) {
  const [scrolled, setScrolled] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  useEffect(() => {
    const onScroll = () => setScrolled(window.scrollY > 60);
    window.addEventListener("scroll", onScroll);
    return () => window.removeEventListener("scroll", onScroll);
  }, []);

  const go = (p: Page) => {
    setPage(p);
    setMenuOpen(false);
  };

  return (
    <nav
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-500 ${
        scrolled
          ? "bg-background/95 backdrop-blur-xl border-b border-[#C9A84C]/12"
          : "bg-transparent"
      }`}
    >
      <div className="max-w-7xl mx-auto px-6 lg:px-8 h-20 flex items-center justify-between">
        <button
          onClick={() => go("home")}
          className="flex items-center gap-3"
        >
          <RoyalTeamLogo size={46} />
          <div className="hidden sm:block leading-none">
            <div
              className="text-[#C9A84C] text-sm font-bold tracking-[0.18em] uppercase"
              style={{ fontFamily: "'Rajdhani', sans-serif" }}
            >
              Royal-Team
            </div>
            <div
              className="text-foreground/40 text-[10px] tracking-[0.12em] uppercase mt-0.5"
              style={{
                fontFamily: "'JetBrains Mono', monospace",
              }}
            >
              Autószerviz
            </div>
          </div>
        </button>

        <div className="hidden xl:flex items-center gap-6">
          {NAV_LINKS.map(({ label, page: p }) => (
            <button
              key={p}
              onClick={() => go(p)}
              className={`text-xs tracking-[0.15em] uppercase transition-colors duration-200 font-semibold ${
                page === p
                  ? "text-[#C9A84C]"
                  : "text-foreground/50 hover:text-foreground/90"
              }`}
              style={{ fontFamily: "'Rajdhani', sans-serif" }}
            >
              {label}
            </button>
          ))}
        </div>

        <div className="flex items-center gap-4">
          <button
            onClick={() => setDark(!dark)}
            className="p-2 text-foreground/40 hover:text-[#C9A84C] transition-colors"
            aria-label="Toggle theme"
          >
            {dark ? <Sun size={17} /> : <Moon size={17} />}
          </button>

          <a
            href="tel:+3612345678"
            className="hidden md:flex items-center gap-2 text-[#C9A84C] text-xs font-medium hover:text-[#E8C040] transition-colors"
            style={{
              fontFamily: "'JetBrains Mono', monospace",
            }}
          >
            <Phone size={14} />
            +36 1 234 5678
          </a>

          <button
            className="xl:hidden p-2 text-foreground/60"
            onClick={() => setMenuOpen(!menuOpen)}
          >
            {menuOpen ? <X size={22} /> : <Menu size={22} />}
          </button>
        </div>
      </div>

      <AnimatePresence>
        {menuOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: "auto" }}
            exit={{ opacity: 0, height: 0 }}
            className="xl:hidden bg-background/98 backdrop-blur-xl border-b border-[#C9A84C]/10 overflow-hidden"
          >
            <div className="px-6 py-6 space-y-1">
              {NAV_LINKS.map(({ label, page: p }) => (
                <button
                  key={p}
                  onClick={() => go(p)}
                  className={`block w-full text-left text-xs tracking-[0.2em] uppercase py-3 border-b border-border/20 font-semibold transition-colors ${
                    page === p
                      ? "text-[#C9A84C]"
                      : "text-foreground/50"
                  }`}
                  style={{
                    fontFamily: "'Rajdhani', sans-serif",
                  }}
                >
                  {label}
                </button>
              ))}
              <a
                href="tel:+3612345678"
                className="flex items-center gap-2 text-[#C9A84C] text-xs pt-4 font-medium"
                style={{
                  fontFamily: "'JetBrains Mono', monospace",
                }}
              >
                <Phone size={14} />
                +36 1 234 5678
              </a>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
}

